79	    /**
80	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
81	     * owner's id, customer code, registration date and membership level, so audit side-effects can
82	     * be observed independently of the HTTP response.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
