86	    /**
87	     * Common street-type abbreviations expanded during address normalization. Keys and values are
88	     * upper-cased, matching the state of the address after whitespace and case normalization.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
91	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
92	
93	    /**
94	     * Required national-number length per E.164 country calling code. After normalization the leading
95	     * country code is stripped and the remaining national digits must match the expected count exactly
96	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
97	     * here are only subject to the generic E.164 length bounds.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
100	        Map.of("1", 10, "61", 9);
