145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        validateRequiredOwnerFields(ownerFieldsDto);
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
152	        owner.setTelephone(normalizedTelephone);
153	        owner.setEmail(normalizeEmail(owner.getEmail()));
154	        owner.setAddress(normalizeAddress(owner.getAddress()));
155	        LocalDate effectiveRegistrationDate =
156	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
157	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
158	        rejectDuplicateTelephone(normalizedTelephone);
159	        rejectDuplicateEmail(owner.getEmail());
160	        rejectDailyLimitReached(owner.getRegistrationDate());
161	        rejectCityAtCapacity(owner.getCity());
162	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
163	            assignHousehold(owner);
164	        } else {
165	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
166	        }
167	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
168	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
169	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
170	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
174	            ownerMapper.membershipLevel(owner));
175	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
