275	    /**
276	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
277	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
278	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
279	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
280	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
281	     * Springfield gets {@code 'SPR-SMI-0011'}.
282	     *
283	     * @param city the owner's city
284	     * @param lastName the owner's last name
285	     * @return the assigned customer code
286	     */
287	    /**
288	     * Counts how many existing owners share the given first and last name, compared
289	     * case-insensitively, at the moment before the new owner is persisted. The result is
290	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
291	     * stood when the owner was created rather than being recomputed on later reads.
292	     *
293	     * @param firstName the first name of the owner being created
294	     * @param lastName the last name of the owner being created
295	     * @return the number of pre-existing owners with the same first and last name
296	     */
297	    private int countNamesakes(String firstName, String lastName) {
298	        String first = firstName == null ? "" : firstName;
299	        String last = lastName == null ? "" : lastName;
300	        return (int) this.clinicService.findAllOwners().stream()
301	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
302	                && last.equalsIgnoreCase(existing.getLastName()))
303	            .count();
304	    }
305	
306	    private String nextCustomerCode(String city, String lastName) {
307	        String cityLetters = city == null ? "" : city;
308	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
309	        String letters = lastName == null ? "" : lastName;
310	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
311	        String normalizedCity = normalizeForComparison(city);
312	        int sequence = (int) this.clinicService.findAllOwners().stream()
313	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
314	            .count() + 1;
315	        return String.format("%s-%s-%04d", city3, last3, sequence);
316	    }
317	
318	    /**
319	     * Rejects an owner payload that is missing or blank in any of the required fields
320	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
321	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
322	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
323	     * guard enforces the rule uniformly for every required field.
324	     *
325	     * @param ownerFieldsDto the submitted owner payload
326	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
327	     */
328	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
329	        List<String> invalidFields = new ArrayList<>();
330	        if (isBlank(ownerFieldsDto.getFirstName())) {
331	            invalidFields.add("firstName");
332	        }
333	        if (isBlank(ownerFieldsDto.getLastName())) {
334	            invalidFields.add("lastName");
335	        }
336	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
337	            invalidFields.add("address");
338	        }
339	        if (isBlank(ownerFieldsDto.getCity())) {
340	            invalidFields.add("city");
341	        }
342	        if (isBlank(ownerFieldsDto.getTelephone())) {
343	            invalidFields.add("telephone");
344	        }
345	        if (!invalidFields.isEmpty()) {
346	            throw new InvalidOwnerFieldsException(invalidFields);
347	        }
348	    }
349	
350	    private boolean isBlank(String value) {
351	        return value == null || value.isBlank();
352	    }
353	
354	    /**
355	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
356	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
357	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
358	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
359	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
360	     *
361	     * @param telephone the raw telephone value from the submitted owner payload
362	     * @return the normalized E.164 telephone number
363	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
364	     */
365	    private String normalizeTelephone(String telephone) {
366	        String raw = telephone == null ? "" : telephone.strip();
367	        boolean hasCountryCode = raw.startsWith("+");
368	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
369	        String digits;
370	        if (hasCountryCode) {
371	            digits = cleaned.substring(1);
372	        } else {
373	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
374	            digits = "61" + national;
375	        }
376	        if (!digits.matches("[0-9]{8,15}")) {
377	            throw new InvalidOwnerFieldsException(List.of("telephone"));
378	        }
379	        validateNationalNumberLength(digits);
380	        return "+" + digits;
381	    }
382	
383	    /**
384	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
385	     * country calling code) has the exact length required for that country. The country code is matched
386	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
387	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
388	     *
389	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
390	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
391	     */
392	    private void validateNationalNumberLength(String digits) {
393	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
394	            String countryCode = entry.getKey();
395	            if (digits.startsWith(countryCode)) {
396	                int nationalLength = digits.length() - countryCode.length();
397	                if (nationalLength != entry.getValue()) {
398	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
399	                }
400	                return;
401	            }
402	        }
403	    }
404	
405	    /**
406	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
407	     * returning {@code null} when the value cannot form a valid E.164 number.
408	     *
409	     * @param telephone an existing owner's stored telephone value
410	     * @return the E.164 form, or {@code null} if it cannot be normalized
411	     */
412	    private String toE164OrNull(String telephone) {
413	        try {
414	            return normalizeTelephone(telephone);
415	        } catch (InvalidOwnerFieldsException ex) {
416	            return null;
417	        }
418	    }
419	
420	    /**
421	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
422	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
423	     * accepted value is trimmed and lower-cased before it is stored and returned.
424	     *
425	     * @param email the raw email value from the submitted owner payload, may be {@code null}
426	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
427	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
428	     */
429	    private String normalizeEmail(String email) {
430	        if (email == null) {
431	            return null;
432	        }
433	        String trimmed = email.strip();
434	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
435	            throw new InvalidOwnerFieldsException(List.of("email"));
436	        }
437	        return trimmed.toLowerCase(Locale.ROOT);
438	    }
439	
440	    /**
441	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
442	     * Existing owners' telephones are converted to E.164 form before comparison so that
443	     * differently-formatted representations of the same number are treated as duplicates.
444	     *
445	     * @param normalizedTelephone the E.164 telephone of the owner being created
446	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
447	     */
448	    private void rejectDuplicateTelephone(String normalizedTelephone) {
449	        boolean duplicate = this.clinicService.findAllOwners().stream()
450	            .map(Owner::getTelephone)
451	            .filter(telephone -> telephone != null)
452	            .map(this::toE164OrNull)
453	            .filter(telephone -> telephone != null)
454	            .anyMatch(normalizedTelephone::equals);
455	        if (duplicate) {
456	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
457	        }
458	    }
459	
460	    /**
461	     * Rejects creating an owner whose lower-cased email is already used by any other owner. The email
462	     * of the owner being created has already been normalized (trimmed and lower-cased) by
463	     * {@link #normalizeEmail}; existing owners' emails are lower-cased before comparison so that
464	     * differently-cased representations of the same address are treated as duplicates. Owners without
465	     * an email (the field is optional) are ignored, and a {@code null} email for the new owner skips
466	     * the check entirely.
467	     *
468	     * @param normalizedEmail the lower-cased email of the owner being created, may be {@code null}
469	     * @throws DuplicateOwnerEmailException if another owner already uses the same lower-cased email
470	     */
471	    private void rejectDuplicateEmail(String normalizedEmail) {
472	        if (normalizedEmail == null) {
473	            return;
474	        }
475	        boolean duplicate = this.clinicService.findAllOwners().stream()
476	            .map(Owner::getEmail)
477	            .filter(email -> email != null)
478	            .map(email -> email.toLowerCase(Locale.ROOT))
479	            .anyMatch(normalizedEmail::equals);
480	        if (duplicate) {
481	            throw new DuplicateOwnerEmailException(normalizedEmail);
482	        }
483	    }
484	
485	    /**
486	     * The maximum number of owners a single city may contain. Once a city already holds this many
487	     * owners, creating another owner in that city is rejected.
488	     */
489	    private static final int MAX_OWNERS_PER_CITY = 50;
490	
491	    /**
492	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
493	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
494	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
495	     * counting used elsewhere.
496	     *
497	     * @param city the city of the owner being created
498	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
499	     */
500	    /**
501	     * The maximum number of owners that may be registered on a single day. Once this many owners
502	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
503	     */
504	    private static final int MAX_OWNERS_PER_DAY = 100;
505	
506	    /**
507	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
508	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
509	     * registration date of the owner being created.
510	     *
511	     * @param registrationDate the registration date of the owner being created
512	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
513	     */
514	    /**
515	     * Rolls an effective registration date forward onto a business day. A registration date must fall
516	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
517	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
518	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
519	     * count, the membership number's year segment, and so on) uses this adjusted date.
520	     *
521	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
522	     * @return the same date if it is a weekday, otherwise the following Monday
523	     */
524	    private LocalDate rollToBusinessDay(LocalDate date) {
525	        DayOfWeek day = date.getDayOfWeek();
526	        if (day == DayOfWeek.SATURDAY) {
527	            return date.plusDays(2);
528	        }
529	        if (day == DayOfWeek.SUNDAY) {
530	            return date.plusDays(1);
531	        }
532	        return date;
533	    }
534	
535	    private void rejectDailyLimitReached(LocalDate registrationDate) {
536	        long ownersToday = this.clinicService.findAllOwners().stream()
537	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
538	            .count();
539	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
540	            throw new DailyOwnerLimitExceededException(registrationDate);
541	        }
542	    }
543	
544	    /**
545	     * The number of owners that must already share a {@code registrationDate} before a newly created
546	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
547	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
548	     */
549	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
550	
551	    /**
552	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
553	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
554	     * the same registration date at the time this owner is created. Existing owners are counted by their
555	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
556	     * daily create-limit accumulation.
557	     *
558	     * @param registrationDate the registration date of the owner being created
559	     * @return {@code true} if the day already holds more than the threshold number of owners
560	     */
561	    private boolean isBulkSignupDay(LocalDate registrationDate) {
562	        long ownersToday = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
564	            .count();
565	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
566	    }
567	
568	    private void rejectCityAtCapacity(String city) {
569	        String normalizedCity = normalizeForComparison(city);
570	        long ownersInCity = this.clinicService.findAllOwners().stream()
571	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
572	            .count();
573	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
574	            throw new OwnerCityCapacityExceededException(city);
575	        }
576	    }
577	
578	    /**
579	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
580	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
581	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
582	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
583	     *
584	     * @param lastName the last name of the owner being created
585	     * @param address the address of the owner being created
586	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
587	     */
588	    private void rejectDuplicateHousehold(String lastName, String address) {
589	        String normalizedLastName = normalizeForComparison(lastName);
590	        String normalizedAddress = normalizeAddress(address);
591	        boolean duplicate = this.clinicService.findAllOwners().stream()
592	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
593	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
594	        if (duplicate) {
595	            throw new DuplicateOwnerHouseholdException(lastName, address);
596	        }
597	    }
598	
599	    /**
600	     * Assigns the owner being created a household identifier when the request opts into sharing a
601	     * household. The identifier is a stable value derived from the owner's normalized last name and
602	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
603	     * value regardless of creation order. Any already-existing owner in the same household that has no
604	     * identifier yet is back-filled with the same value so the whole household stays consistent.
605	     *
606	     * @param owner the owner being created, whose household id is set in place
607	     */
608	    private void assignHousehold(Owner owner) {
609	        String householdId = householdId(owner.getLastName(), owner.getAddress());
610	        String normalizedLastName = normalizeForComparison(owner.getLastName());
611	        String normalizedAddress = normalizeAddress(owner.getAddress());
612	        for (Owner existing : this.clinicService.findAllOwners()) {
613	            if (existing.getHouseholdId() == null
614	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
615	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
616	                existing.setHouseholdId(householdId);
617	                this.clinicService.saveOwner(existing);
618	            }
619	        }
620	        owner.setHouseholdId(householdId);
621	    }
622	
623	    /**
624	     * Counts how many owners belong to the household the owner being created has just been assigned to,
625	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
626	     * given identifier; the owner being created is added on because it is counted before being persisted.
627	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
628	     * household of one. The value is snapshotted on the owner.
629	     *
630	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
631	     * @return the number of household members, including the owner being created
632	     */
633	    private int countHousehold(String householdId) {
634	        if (householdId == null) {
635	            return 1;
636	        }
637	        long existing = this.clinicService.findAllOwners().stream()
638	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
639	            .count();
640	        return (int) existing + 1;
641	    }
642	
643	    /**
644	     * Derives the stable household identifier for a given last name and address. The value is
645	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
646	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
647	     * the same household therefore always produce the same identifier.
648	     *
649	     * @param lastName the owner's last name
650	     * @param address the owner's address
651	     * @return the stable household identifier
652	     */
653	    private String householdId(String lastName, String address) {
654	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
655	        try {
656	            byte[] digest = MessageDigest.getInstance("SHA-256")
657	                .digest(key.getBytes(StandardCharsets.UTF_8));
658	            StringBuilder hex = new StringBuilder();
659	            for (int i = 0; i < 6; i++) {
660	                hex.append(String.format("%02X", digest[i]));
661	            }
662	            return "HH-" + hex;
663	        } catch (NoSuchAlgorithmException ex) {
664	            throw new IllegalStateException("SHA-256 not available", ex);
665	        }
666	    }
667	
668	    /**
669	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
670	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
671	     * result is lower-cased. A {@code null} value normalizes to the empty string.
672	     *
673	     * @param value the value to normalize, may be {@code null}
674	     * @return the normalized value
675	     */
676	    private String normalizeForComparison(String value) {
677	        if (value == null) {
678	            return "";
679	        }
680	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
681	    }
682	
683	    /**
684	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
685	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
686	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
687	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
688	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
689	     * that is stored, returned, and used for every address comparison (household duplicate detection
690	     * and the shared household id).
691	     *
692	     * @param address the raw address value from the submitted owner payload, may be {@code null}
693	     * @return the normalized address
694	     */
695	    private String normalizeAddress(String address) {
696	        if (address == null) {
697	            return "";
698	        }
699	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
700	        if (collapsed.isEmpty()) {
701	            return "";
702	        }
703	        String[] tokens = collapsed.split(" ");
704	        StringBuilder normalized = new StringBuilder();
705	        for (int i = 0; i < tokens.length; i++) {
706	            if (i > 0) {
707	                normalized.append(' ');
708	            }
709	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
710	        }
711	        return normalized.toString();
712	    }
713	}
